    t.link('Reroute', 'Output', 'Group.006', 'Vector')
    t.link('eyeshadowuv', 'UV', 'Group.005', 'Vector')
    t.link('Reroute', 'Output', 'Group.007', 'UV Map')
    t.link('Reroute.001', 'Output', 'Group.008', 'UV Map')
    t.link('Group.007', 'Coordinates', 'Group Output', 'Lipstick position')
